INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a446ae01sj7s0rakm6hj8', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'note', 'published', 'public', NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Repotted the balcony herbs before breakfast. Basil was dramatic. Mint did not care at all."}]}]}', '<p>Repotted the balcony herbs before breakfast. Basil was dramatic. Mint did not care at all.</p>', 'Repotted the balcony herbs before breakfast. Basil was dramatic. Mint did not care at all.', NULL, NULL, NULL, NULL, 'pst_01km9a446ae01sj7s0rakm6hj8', NULL, 1758960900, 1758991800, 1774134104, 1774134104);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a4512e01sj7sq24ze3dep', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'note', 'published', NULL, NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I keep forgetting that plants mostly want consistency, not inspiration. Fair enough."}]}]}', '<p>I keep forgetting that plants mostly want consistency, not inspiration. Fair enough.</p>', 'I keep forgetting that plants mostly want consistency, not inspiration. Fair enough.', NULL, NULL, NULL, 'pst_01km9a446ae01sj7s0rakm6hj8', 'pst_01km9a446ae01sj7s0rakm6hj8', NULL, 1758963600, 1758963600, 1774134105, 1774134105);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a45q9e01sj7t0npf1chpq', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'link', 'published', NULL, NULL, NULL, 'The potting mix guide I keep rereading', 'https://www.rhs.org.uk/plants/types/houseplants/repotting', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Basic, clear, and good for confidence when I start overthinking dirt."}]}]}', '<p>Basic, clear, and good for confidence when I start overthinking dirt.</p>', 'Basic, clear, and good for confidence when I start overthinking dirt.', NULL, NULL, NULL, 'pst_01km9a446ae01sj7s0rakm6hj8', 'pst_01km9a446ae01sj7s0rakm6hj8', NULL, 1758966000, 1758966000, 1774134105, 1774134105);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a46xfe01sj7ttgajv0yjv', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'note', 'published', NULL, NULL, NULL, NULL, NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"By late afternoon the basil was standing up again. I respect a fast recovery."}]}]}', '<p>By late afternoon the basil was standing up again. I respect a fast recovery.</p>', 'By late afternoon the basil was standing up again. I respect a fast recovery.', NULL, NULL, NULL, 'pst_01km9a446ae01sj7s0rakm6hj8', 'pst_01km9a446ae01sj7s0rakm6hj8', NULL, 1758991800, 1758991800, 1774134107, 1774134107);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a47mee01sj7vbmvxktmkn', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'link', 'published', 'public', NULL, NULL, 'A night heron field guide for my walk folder', 'https://www.audubon.org/field-guide/bird/black-crowned-night-heron', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Posting this here so I can find it again the next time I see a suspiciously patient bird near the water."}]}]}', '<p>Posting this here so I can find it again the next time I see a suspiciously patient bird near the water.</p>', 'Posting this here so I can find it again the next time I see a suspiciously patient bird near the water.', NULL, NULL, 4, NULL, 'pst_01km9a47mee01sj7vbmvxktmkn', NULL, 1772701800, 1772701800, 1774134107, 1774134107);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a488pe01sj7vzb2ndq0wj', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'note', 'published', 'public', NULL, 1774134108, 'A Quiet Saturday After a Busy Week', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind."}]},{"type":"paragraph","content":[{"type":"text","text":"Breakfast took an hour. I opened the windows even though it was still cold. I put the phone on the bookshelf and left it there long enough to hear the apartment settle down."}]},{"type":"moreBreak"},{"type":"paragraph","content":[{"type":"text","text":"What helped most was not turning the free day into a project. I made coffee, wiped the kitchen counter, read twenty pages, and sat in the chair by the window without trying to optimize anything."}]},{"type":"paragraph","content":[{"type":"text","text":"A good day does not always need a headline. Sometimes it only needs enough room to happen."}]}]}', '<p>Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind.</p><p>Breakfast took an hour. I opened the windows even though it was still cold. I put the phone on the bookshelf and left it there long enough to hear the apartment settle down.</p><!--more--><p>What helped most was not turning the free day into a project. I made coffee, wiped the kitchen counter, read twenty pages, and sat in the chair by the window without trying to optimize anything.</p><p>A good day does not always need a headline. Sometimes it only needs enough room to happen.</p>', 'Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind. Breakfast took an hour. I opened the windows even though it was still cold. I put the phone on the bookshelf and left it there long enough to hear the apartment settle down. What helped most was not turning the free day into a project. I made coffee, wiped the kitchen counter, read twenty pages, and sat in the chair by the window without trying to optimize anything. A good day does not always need a headline. Sometimes it only needs enough room to happen.', NULL, 'Last week felt like six weeks compressed into five days. I spent most of it answering things, moving things, and promising myself I would slow down later. Today was the later I had in mind.
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a493ee01sj7wdccw9d3t9', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'link', 'published', 'public', NULL, NULL, 'Are.na is the only bookmark pile I still revisit', 'https://www.are.na/', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most saved links disappear into a hole. This one still feels calm enough to browse on purpose."}]}]}', '<p>Most saved links disappear into a hole. This one still feels calm enough to browse on purpose.</p>', 'Most saved links disappear into a hole. This one still feels calm enough to browse on purpose.', NULL, NULL, 4, NULL, 'pst_01km9a493ee01sj7wdccw9d3t9', NULL, 1760537700, 1760537700, 1774134109, 1774134109);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a4a5be01sj7x7bg4tsgtb', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'note', 'published', 'public', NULL, NULL, 'Bought Too Many Lemons Again', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be."}]},{"type":"paragraph","content":[{"type":"text","text":"This keeps happening. I think part of me believes citrus counts as a plan."}]}]}', '<p>Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be.</p><p>This keeps happening. I think part of me believes citrus counts as a plan.</p>', 'Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be. This keeps happening. I think part of me believes citrus counts as a plan.', NULL, 'Came home from the market with a bag of lemons, parsley, eggs, and zero idea what dinner was going to be.
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a4atne01sj7xp11h8kwm0', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'note', 'published', 'public', NULL, NULL, 'Current Tea Rotation', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The kitchen shelf is doing a lot of work right now."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jasmine for late afternoons"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Black tea when I need to become a person quickly"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mint tea after dinner when I want the day to stop talking"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Nothing profound here. I just like having a small system for ordinary comfort."}]}]}', '<p>The kitchen shelf is doing a lot of work right now.</p><ul><li><p>Jasmine for late afternoons</p></li><li><p>Black tea when I need to become a person quickly</p></li><li><p>Mint tea after dinner when I want the day to stop talking</p></li></ul><p>Nothing profound here. I just like having a small system for ordinary comfort.</p>', 'The kitchen shelf is doing a lot of work right now. Jasmine for late afternoons Black tea when I need to become a person quickly Mint tea after dinner when I want the day to stop talking Nothing profound here. I just like having a small system for ordinary comfort.', NULL, 'The kitchen shelf is doing a lot of work right now.
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a4bg7e01sj7y6we7ydtsa', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'link', 'published', 'public', NULL, NULL, 'Derek Sivers still writes the kind of internet I want more of', 'https://sive.rs/', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Short pages, clear opinions, no inflation. I usually leave with one useful sentence and that is enough."}]}]}', '<p>Short pages, clear opinions, no inflation. I usually leave with one useful sentence and that is enough.</p>', 'Short pages, clear opinions, no inflation. I usually leave with one useful sentence and that is enough.', NULL, NULL, 4, NULL, 'pst_01km9a4bg7e01sj7y6we7ydtsa', NULL, 1764060600, 1764060600, 1774134111, 1774134111);
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a4c49e01sj7ykmm2f232w', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'note', 'published', 'public', 1774134112, NULL, 'Desk, But Better', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I finally made the desk simple enough that I want to sit down there again."}]},{"type":"paragraph","content":[{"type":"text","text":"The rule is now: laptop, lamp, notebook, water. If something else lives there, it has to earn the space."}]}]}', '<p>I finally made the desk simple enough that I want to sit down there again.</p><p>The rule is now: laptop, lamp, notebook, water. If something else lives there, it has to earn the space.</p>', 'I finally made the desk simple enough that I want to sit down there again. The rule is now: laptop, lamp, notebook, water. If something else lives there, it has to earn the space.', NULL, 'I finally made the desk simple enough that I want to sit down there again.
