INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a5378e01sj8f3d3e42b5z', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'note', 'published', 'public', NULL, NULL, 'The Five-Minute Reset Is Still the Best Habit I Have', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the apartment starts feeling loud, I set a five-minute timer and do the same small loop:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dishes into the sink"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"clothes off the chair"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"papers into one stack"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"window cracked open"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"It does not fix everything, but it changes the room enough that I stop feeling stuck in it."}]}]}', '<p>When the apartment starts feeling loud, I set a five-minute timer and do the same small loop:</p><ul><li><p>dishes into the sink</p></li><li><p>clothes off the chair</p></li><li><p>papers into one stack</p></li><li><p>window cracked open</p></li></ul><p>It does not fix everything, but it changes the room enough that I stop feeling stuck in it.</p>', 'When the apartment starts feeling loud, I set a five-minute timer and do the same small loop: dishes into the sink clothes off the chair papers into one stack window cracked open It does not fix everything, but it changes the room enough that I stop feeling stuck in it.', NULL, 'When the apartment starts feeling loud, I set a five-minute timer and do the same small loop:
INSERT INTO "post" ("id", "site_id", "format", "status", "visibility", "pinned_at", "featured_at", "title", "url", "body", "body_html", "body_text", "quote_text", "summary", "rating", "reply_to_id", "thread_id", "deleted_at", "published_at", "last_activity_at", "created_at", "updated_at") VALUES('pst_01km9a53tde01sj8fnkmtcgbpy', 'sit_01km8yx7gwfqb9exhmdmv237b4', 'note', 'published', 'public', NULL, NULL, 'The Hallway Light Took 12 Minutes and 3 Months', NULL, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie."}]},{"type":"paragraph","content":[{"type":"text","text":"Today I bought the new bulb, climbed the stool, changed it, and laughed at how small the actual job was."}]},{"type":"paragraph","content":[{"type":"text","text":"This is the kind of tiny project I avoid for no good reason. The dread is usually larger than the task."}]}]}', '<p>The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie.</p><p>Today I bought the new bulb, climbed the stool, changed it, and laughed at how small the actual job was.</p><p>This is the kind of tiny project I avoid for no good reason. The dread is usually larger than the task.</p>', 'The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie. Today I bought the new bulb, climbed the stool, changed it, and laughed at how small the actual job was. This is the kind of tiny project I avoid for no good reason. The dread is usually larger than the task.', NULL, 'The bulb burned out in June. I meant to replace it the same day. Instead I spent three months walking through the hallway like somebody in a low-budget mystery movie.
